<?php
namespace App\Http\Controllers;
use App\Models\{Product,Category,Order,Enquiry}; use Illuminate\Http\Request; use Illuminate\Support\Str;
class AdminController extends Controller { public function dashboard(){return view('admin.dashboard',['products'=>Product::count(),'orders'=>Order::count(),'enquiries'=>Enquiry::where('status','new')->count(),'revenue'=>Order::where('payment_status','paid')->sum('total')]);} public function products(){return view('admin.products.index',['products'=>Product::with('category')->latest()->paginate(20)]);} public function productCreate(){return view('admin.products.form',['product'=>new Product,'categories'=>Category::all()]);} public function productStore(Request $r){$d=$r->validate(['category_id'=>'required|exists:categories,id','name'=>'required|max:150','description'=>'nullable','price'=>'nullable|numeric|min:0','price_on_request'=>'boolean','stock'=>'required|integer|min:0','image'=>'nullable|string|max:255','badge'=>'nullable|max:50','is_active'=>'boolean','featured'=>'boolean']);$d['slug']=Str::slug($d['name']).'-'.Str::lower(Str::random(5));Product::create($d);return redirect()->route('admin.products')->with('success','Product created.');} public function productEdit(Product $product){return view('admin.products.form',compact('product')+['categories'=>Category::all()]);} public function productUpdate(Request $r,Product $product){$d=$r->validate(['category_id'=>'required|exists:categories,id','name'=>'required|max:150','description'=>'nullable','price'=>'nullable|numeric|min:0','price_on_request'=>'boolean','stock'=>'required|integer|min:0','image'=>'nullable|string|max:255','badge'=>'nullable|max:50','is_active'=>'boolean','featured'=>'boolean']);$product->update($d);return back()->with('success','Product updated.');} public function productDelete(Product $product){$product->delete();return back()->with('success','Product deleted.');} public function categories(){return view('admin.categories.index',['categories'=>Category::withCount('products')->latest()->get()]);} public function categoryStore(Request $r){$d=$r->validate(['name'=>'required|max:100','description'=>'nullable']);Category::create(['name'=>$d['name'],'slug'=>Str::slug($d['name']), 'description'=>$d['description']??null]);return back()->with('success','Category created.');} public function categoryDelete(Category $category){$category->delete();return back()->with('success','Category deleted.');} public function orders(){return view('admin.orders.index',['orders'=>Order::with('items')->latest()->paginate(20)]);} public function orderUpdate(Request $r,Order $order){$d=$r->validate(['status'=>'required|in:pending,confirmed,processing,shipped,completed,cancelled','payment_status'=>'required|in:unpaid,paid,refunded']);$order->update($d);return back()->with('success','Order updated.');} public function enquiries(){return view('admin.enquiries.index',['enquiries'=>Enquiry::latest()->paginate(20)]);} public function enquiryUpdate(Request $r,Enquiry $enquiry){$r->validate(['status'=>'required|in:new,read,resolved']);$enquiry->update(['status'=>$r->status]);return back()->with('success','Enquiry updated.');} }
